import manifest from "./reference-images.json";

/**
 * Reference imagery for the curated targets, with provenance.
 * Generated by scripts/fetch-reference-images.mjs; do not edit the JSON by hand.
 */

interface ReferenceSource {
  name: string;
  pageUrl: string;
  credit: string;
  license: string;
  licenseUrl?: string;
  description: string;
  retrievedAt: string;
  queryUrls?: string[];
}

interface ReferenceImageBase {
  targetId: string;
  src: string;
  widthPx: number;
  heightPx: number;
  source: ReferenceSource;
  processing: string;
  notes: string[];
}

/** A photograph cropped to the body: image width = the target's major axis. */
export interface BodyReferenceImage extends ReferenceImageBase {
  kind: "body";
}

/** A sky-survey cutout centred on the target with a known angular size. */
export interface FieldReferenceImage extends ReferenceImageBase {
  kind: "field";
  /** The same image with stars removed, for drawing catalogue stars over it. */
  objectSrc?: string;
  objectProcessing?: string;
  fieldWidthArcsec: number;
  fieldHeightArcsec: number;
  center: { raDeg: number; decDeg: number };
}

export type ReferenceImage = BodyReferenceImage | FieldReferenceImage;

const IMAGES = manifest.images as ReferenceImage[];

export function getReferenceImage(targetId: string): ReferenceImage | undefined {
  return IMAGES.find((i) => i.targetId === targetId);
}
